    namespace = "dev.kuclab.clock"
    compileSdk = 34

    defaultConfig {
        applicationId = "dev.kuclab.clock"
        minSdk = 26
        targetSdk = 34
        versionCode = 4
        versionName = "1.3"
    }

    signingConfigs {
        if (kuclabKeystore.exists()) {
            create("kuclab") {
                storeFile = kuclabKeystore
                storePassword = "KucLabClock-signing-2026"
                keyAlias = "kuclab"
                keyPassword = "KucLabClock-signing-2026"
            }
        }
    }

    buildTypes {
